import type { Context } from "hono"
import type { SSEStreamingApi } from "hono/streaming"

import consola from "consola"
import { streamSSE } from "hono/streaming"

export interface StreamSSEOptions {
  /** Request signal; an abort on it means the client went away. */
  signal?: AbortSignal
  /** Label used when logging a client disconnect. */
  label: string
  /** Writes a format-specific terminal event for non-abort failures. */
  onError?: (stream: SSEStreamingApi, error: unknown) => Promise<void> | void
  /** Reports that the upstream already emitted an in-band terminal error. */
  hasTerminalError?: () => boolean
}

/**
 * Wrap an SSE producer so that a client disconnect ends the stream quietly.
 *
 * A disconnect shows up either as an already-aborted request signal or as an
 * `AbortError` thrown while the upstream stream is being consumed. Neither is a
 * failure worth surfacing, so the stream simply ends. Other failures are
 * converted by the optional format-specific writer or rethrown when absent.
 *
 * This is the single definition of what "the client went away" means; it
 * previously existed as five structurally identical copies across the two route
 * handlers.
 */
export function streamSSEWithAbort(
  c: Context,
  { signal, label, onError, hasTerminalError }: StreamSSEOptions,
  produce: (stream: SSEStreamingApi) => Promise<void>,
): Response {
  return streamSSE(c, async (stream) => {
    try {
      await produce(stream)
    } catch (error) {
      if (isClientAbort(error, signal)) {
        consola.debug(`${label} stream aborted by client`)
        return
      }
      const errorName = error instanceof Error ? error.name : typeof error
      consola.error(`${label} stream failed (${errorName})`)
      if (hasTerminalError?.()) return
      if (!onError) throw error
      try {
        await onError(stream, error)
      } catch (writeError) {
        consola.debug(
          `${label} terminal error event could not be written`,
          writeError,
        )
      }
    }
  })
}

/**
 * Whether an error ending a stream means the client went away.
 *
 * Exported because this predicate is the only real logic in this module, and
 * it is not observable through a route: swallowing and rethrowing produce the
 * same client-visible result (headers are already sent, so both end as HTTP
 * 200 with a partial body and a clean EOF). It therefore has to be tested
 * directly.
 */
export function isClientAbort(error: unknown, signal?: AbortSignal): boolean {
  return (
    signal?.aborted === true
    || (error instanceof Error && error.name === "AbortError")
  )
}

export const STREAM_TRANSPORT_ERROR = {
  type: "api_error",
  code: "stream_transport_error",
  message: "The upstream stream terminated unexpectedly.",
} as const

export async function writeOpenAIStreamError(
  stream: SSEStreamingApi,
): Promise<void> {
  await stream.writeSSE({
    data: JSON.stringify({
      error: {
        type: STREAM_TRANSPORT_ERROR.type,
        code: STREAM_TRANSPORT_ERROR.code,
        message: STREAM_TRANSPORT_ERROR.message,
        param: null,
      },
    }),
  })
}

import type { Context } from "hono"

import consola from "consola"
import { type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { streamSSEWithAbort, writeOpenAIStreamError } from "~/lib/streaming"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import {
  createChatCompletions,
  type ChatCompletionChunk,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  if (isNullish(payload.max_tokens)) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const result = await createChatCompletions(payload, signal)

  if (result.kind === "object") {
    consola.debug("Non-streaming response:", JSON.stringify(result.body))
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "chat-completions",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        terminalErrorSeen ||= Boolean((chunk as ChatCompletionChunk).error)
        await stream.writeSSE(chunk as SSEMessage)
      }
    },
  )
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const result = await createResponses(payload, effort, signal)

  if (result.kind === "object") {
    consola.debug(
      "Non-streaming /responses result:",
      JSON.stringify(result.body),
    )
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming /responses response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/responses",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createResponsesStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          terminalErrorSeen ||= Boolean(chunk.error)
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    },
  )
}

import type { Context } from "hono"
import type { SSEStreamingApi } from "hono/streaming"

import consola from "consola"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { anthropicToCopilotModelId } from "~/lib/model-mapping"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { STREAM_TRANSPORT_ERROR, streamSSEWithAbort } from "~/lib/streaming"
import {
  createChatCompletions,
  type ChatCompletionChunk,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"
import {
  forwardNativeMessagesNonStreaming,
  forwardNativeMessagesStreaming,
} from "~/services/copilot/forward-native-messages"

import {
  createAnthropicStreamState,
  type AnthropicMessagesPayload,
} from "./anthropic-types"
import {
  translateToAnthropic,
  translateToOpenAI,
} from "./non-stream-translation"
import {
  translateChunkToAnthropicEvents,
  translateErrorToAnthropicErrorEvent,
} from "./stream-translation"

const CONTEXT_1M_BETA = "context-1m-2025-08-07"

async function writeAnthropicStreamError(
  stream: SSEStreamingApi,
): Promise<void> {
  const event = translateErrorToAnthropicErrorEvent({
    type: STREAM_TRANSPORT_ERROR.type,
    message: STREAM_TRANSPORT_ERROR.message,
  })
  await stream.writeSSE({
    event: event.type,
    data: JSON.stringify(event),
  })
}

/**
 * Check if the request wants 1M context via the anthropic-beta header.
 * The Claude Agent SDK sets `anthropic-beta: context-1m-2025-08-07`
 * instead of appending [1m] to the model name.
 */
function detectWants1M(c: Context): boolean {
  const betaHeader = c.req.header("anthropic-beta") ?? ""
  return betaHeader.split(",").some((s) => s.trim() === CONTEXT_1M_BETA)
}

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  const anthropicPayload = await c.req.json<AnthropicMessagesPayload>()
  consola.debug("Anthropic request payload:", JSON.stringify(anthropicPayload))

  if (state.manualApprove) {
    await awaitApproval()
  }

  // Check per-request 1M context: anthropic-beta header or global flag
  const wants1M = detectWants1M(c) || state.is1MContext

  const copilotModelId = anthropicToCopilotModelId(
    anthropicPayload.model,
    wants1M,
  )
  const endpoint = resolveEndpoint(copilotModelId, state.models)
  const signal = c.req.raw.signal

  // Native Anthropic passthrough for Claude models
  if (endpoint === "/v1/messages") {
    consola.debug(`Using native /v1/messages passthrough for ${copilotModelId}`)
    return handleNativePassthrough(c, anthropicPayload, wants1M, signal)
  }

  // Translate Anthropic → OpenAI format for non-Claude models
  const openAIPayload = translateToOpenAI(anthropicPayload)
  consola.debug(
    "Translated OpenAI request payload:",
    JSON.stringify(openAIPayload),
  )

  // /responses for GPT-5.x models (responses-only or preferred)
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for ${copilotModelId}`)
    const effort = resolveEffort({
      modelId: copilotModelId,
      requested: anthropicPayload.output_config?.effort,
      cachedModels: state.models,
      defaultEffort: "medium",
    })
    return handleResponsesViaAnthropic({
      context: c,
      openAIPayload,
      effort,
      signal,
    })
  }

  // /chat/completions for legacy models
  openAIPayload.reasoning_effort = resolveEffort({
    modelId: copilotModelId,
    requested: anthropicPayload.output_config?.effort,
    cachedModels: state.models,
  })
  const result = await createChatCompletions(openAIPayload, signal)

  if (result.kind === "object") {
    consola.debug(
      "Non-streaming response from Copilot:",
      JSON.stringify(result.body).slice(-400),
    )
    const anthropicResponse = translateToAnthropic(result.body)
    consola.debug(
      "Translated Anthropic response:",
      JSON.stringify(anthropicResponse),
    )
    return c.json(anthropicResponse)
  }
  const response = result.stream

  consola.debug("Streaming response from Copilot")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/v1/messages chat-completions",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        consola.debug("Copilot raw stream event:", JSON.stringify(rawEvent))
        if (rawEvent.data === "[DONE]") {
          break
        }

        if (!rawEvent.data) {
          continue
        }

        const chunk = JSON.parse(rawEvent.data) as ChatCompletionChunk
        const events = translateChunkToAnthropicEvents(chunk, streamState)

        for (const event of events) {
          consola.debug("Translated Anthropic event:", JSON.stringify(event))
          terminalErrorSeen ||= event.type === "error"
          await stream.writeSSE({
            event: event.type,
            data: JSON.stringify(event),
          })
        }
      }
    },
  )
}

// eslint-disable-next-line max-params
async function handleNativePassthrough(
  c: Context,
  payload: AnthropicMessagesPayload,
  is1M: boolean,
  signal?: AbortSignal,
) {
  if (!payload.stream) {
    const response = await forwardNativeMessagesNonStreaming(
      payload,
      is1M,
      signal,
    )
    return c.json(response)
  }

  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/v1/messages native passthrough",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const event of forwardNativeMessagesStreaming(
        payload,
        is1M,
        signal,
      )) {
        terminalErrorSeen ||= event.type === "error"
        await stream.writeSSE({
          event: event.type,
          data: JSON.stringify(event.data),
        })
      }
    },
  )
}

/**
 * Handle a request that needs the /responses endpoint but arrived via /v1/messages.
 * Flow: Anthropic payload → already translated to OpenAI → /responses → OpenAI response → Anthropic format.
 */
interface ResponsesViaAnthropicOptions {
  context: Context
  openAIPayload: Parameters<typeof createResponses>[0]
  effort?: string
  signal?: AbortSignal
}

async function handleResponsesViaAnthropic({
  context,
  openAIPayload,
  effort,
  signal,
}: ResponsesViaAnthropicOptions) {
  const result = await createResponses(openAIPayload, effort, signal)

  if (result.kind === "object") {
    const anthropicResponse = translateToAnthropic(result.body)
    return context.json(anthropicResponse)
  }
  const response = result.stream

  let terminalErrorSeen = false
  return streamSSEWithAbort(
    context,
    {
      signal,
      label: "/v1/messages /responses",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const responsesState = createResponsesStreamState()
      const anthropicState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          responsesState,
        )

        for (const chunk of chunks) {
          const events = translateChunkToAnthropicEvents(chunk, anthropicState)
          for (const event of events) {
            terminalErrorSeen ||= event.type === "error"
            await stream.writeSSE({
              event: event.type,
              data: JSON.stringify(event),
            })
          }
        }
      }
    },
  )
}

import consola from "consola"
import { events } from "fetch-event-stream"

import type { CopilotUsage, RawCopilotUsage } from "~/lib/copilot-usage"
import type { RequestedEffort } from "~/lib/effort"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { normalizeCopilotUsage } from "~/lib/copilot-usage"
import { HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

import {
  objectResult,
  type ServiceResult,
  streamResult,
} from "./service-result"

export type ChatCompletionStream = ReturnType<typeof events>

export const createChatCompletions = async (
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
): Promise<ServiceResult<ChatCompletionResponse, ChatCompletionStream>> => {
  if (!state.copilotToken) throw new Error("Copilot token not found")

  const enableVision = payload.messages.some(
    (x) =>
      typeof x.content !== "string"
      && x.content?.some((x) => x.type === "image_url"),
  )

  // Agent/user check for X-Initiator header
  // Determine if any message is from an agent ("assistant" or "tool")
  const isAgentCall = payload.messages.some((msg) =>
    ["assistant", "tool"].includes(msg.role),
  )

  // Build headers and add X-Initiator
  const response = await copilotFetch(
    `${copilotBaseUrl(state)}/chat/completions`,
    {
      method: "POST",
      headers: { "X-Initiator": isAgentCall ? "agent" : "user" },
      body: JSON.stringify(payload),
      signal,
    },
    { vision: enableVision },
  )

  if (!response.ok) {
    consola.error("Failed to create chat completions", response)
    throw new HTTPError("Failed to create chat completions", response)
  }

  if (payload.stream) {
    return streamResult(events(response))
  }

  const result = (await response.json()) as ChatCompletionResponse & {
    copilot_usage?: RawCopilotUsage
  }
  result.copilot_usage = normalizeCopilotUsage(result.copilot_usage)
  return objectResult(result)
}

// Streaming types

export interface ChatCompletionChunk {
  id: string
  object: "chat.completion.chunk"
  created: number
  model: string
  choices: Array<Choice>
  system_fingerprint?: string
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
    completion_tokens_details?: {
      accepted_prediction_tokens: number
      rejected_prediction_tokens: number
    }
  }
  error?: {
    type: string
    message: string
    code?: string
  }
}

interface Delta {
  content?: string | null
  role?: "user" | "assistant" | "system" | "tool"
  tool_calls?: Array<{
    index: number
    id?: string
    type?: "function"
    function?: {
      name?: string
      arguments?: string
    }
  }>
}

interface Choice {
  index: number
  delta: Delta
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter" | null
  logprobs: object | null
}

// Non-streaming types

export interface ChatCompletionResponse {
  id: string
  object: "chat.completion"
  created: number
  model: string
  choices: Array<ChoiceNonStreaming>
  system_fingerprint?: string
  copilot_usage?: CopilotUsage
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
  }
}

interface ResponseMessage {
  role: "assistant"
  content: string | null
  reasoning_text?: string | null
  tool_calls?: Array<ToolCall>
}

interface ChoiceNonStreaming {
  index: number
  message: ResponseMessage
  logprobs: object | null
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter"
}

// Payload types

export interface ChatCompletionsPayload {
  messages: Array<Message>
  model: string
  temperature?: number | null
  top_p?: number | null
  max_tokens?: number | null
  stop?: string | Array<string> | null
  n?: number | null
  stream?: boolean | null

  frequency_penalty?: number | null
  presence_penalty?: number | null
  logit_bias?: Record<string, number> | null
  logprobs?: boolean | null
  response_format?: { type: "json_object" } | null
  seed?: number | null
  reasoning_effort?: RequestedEffort
  tools?: Array<Tool> | null
  tool_choice?:
    | "none"
    | "auto"
    | "required"
    | { type: "function"; function: { name: string } }
    | null
  user?: string | null
}

export interface Tool {
  type: "function"
  function: {
    name: string
    description?: string
    parameters: Record<string, unknown>
  }
}

export interface Message {
  role: "user" | "assistant" | "system" | "tool" | "developer"
  content: string | Array<ContentPart> | null

  name?: string
  tool_calls?: Array<ToolCall>
  tool_call_id?: string
}

export interface ToolCall {
  id: string
  type: "function"
  function: {
    name: string
    arguments: string
  }
}

export type ContentPart = TextPart | ImagePart | AudioPart

export interface TextPart {
  type: "text"
  text: string
}

export interface ImagePart {
  type: "image_url"
  image_url: {
    url: string
    detail?: "low" | "high" | "auto"
  }
}

export interface AudioPart {
  type: "input_audio"
  input_audio: {
    data: string
    format: "wav" | "mp3"
  }
}

/* eslint-disable max-lines */
import consola from "consola"
import { events } from "fetch-event-stream"
import { randomUUID } from "node:crypto"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import {
  normalizeCopilotUsage,
  type RawCopilotUsage,
} from "~/lib/copilot-usage"
import { badRequest, HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

import type {
  ChatCompletionChunk,
  ChatCompletionResponse,
  ChatCompletionsPayload,
  ToolCall,
} from "./create-chat-completions"

import {
  objectResult,
  type ServiceResult,
  streamResult,
} from "./service-result"

export type ResponsesStream = ReturnType<typeof events>

interface ResponsesPayload {
  model: string
  input: Array<ResponsesInput>
  max_output_tokens?: number
  tools?: Array<ResponsesTool>
  tool_choice?: string | { type: string; name?: string }
  stream?: boolean
  reasoning?: { effort: string }
}
type ResponsesInput =
  | {
      type: "message"
      role: "developer" | "user" | "assistant"
      content: string | Array<ResponsesContentPart>
    }
  | { type: "function_call"; name: string; arguments: string; call_id: string }
  | { type: "function_call_output"; call_id: string; output: string }
interface ResponsesContentPart {
  type: "input_text" | "input_image" | "input_audio"
  text?: string
  image_url?: string
  detail?: string
  input_audio?: { data: string; format: string }
}
interface ResponsesTool {
  type: "function"
  name: string
  description?: string
  parameters: Record<string, unknown>
}
interface RawContentPart {
  type: string
  text?: string
  image_url?: { url?: string; detail?: string }
  input_audio?: { data?: string; format?: string }
}
export function translateMessageContent(
  content: string | Array<RawContentPart> | undefined,
): string | Array<ResponsesContentPart> {
  if (typeof content === "string") return content
  if (!content) return ""
  const parts: Array<ResponsesContentPart> = []
  for (const p of content) {
    if (p.type === "text") {
      parts.push({ type: "input_text", text: p.text ?? "" })
      continue
    }
    if (p.type === "image_url") {
      const url = p.image_url?.url
      if (!url) {
        consola.warn("Dropping image_url part with no url", {
          reason: "missing image_url.url",
        })
        continue
      }
      parts.push({
        type: "input_image",
        image_url: url,
        detail: p.image_url?.detail,
      })
      continue
    }
    if (p.type === "input_audio") {
      const data = p.input_audio?.data
      const format = p.input_audio?.format
      if (!data || !format) {
        consola.warn("Dropping input_audio part missing data or format", {
          hasData: Boolean(data),
          hasFormat: Boolean(format),
        })
        continue
      }
      parts.push({
        type: "input_audio",
        input_audio: { data, format },
      } as ResponsesContentPart)
      continue
    }
    consola.warn("Dropping unknown content part type", { unknownType: p.type })
  }
  return parts
}
function requireToolCallId(id: string | undefined, field: string): string {
  if (!id) throw badRequest(`${field} is missing`)
  return id
}
function translateMessages(
  messages: ChatCompletionsPayload["messages"],
): Array<ResponsesInput> {
  const input: Array<ResponsesInput> = []
  for (const msg of messages) {
    switch (msg.role) {
      case "system":
      case "developer": {
        input.push({
          type: "message",
          role: "developer",
          content: translateMessageContent(msg.content ?? ""),
        })
        break
      }
      case "user": {
        input.push({
          type: "message",
          role: "user",
          content: translateMessageContent(msg.content ?? ""),
        })
        break
      }
      case "assistant": {
        // TODO: When Copilot starts populating reasoning summaries,
        // we should detect thinking blocks in msg.content and map them
        // to { type: "reasoning", summary: [{type: "summary_text", text}] }
        // instead of sending them as plain assistant text. Currently
        // thinking blocks are concatenated into content by translateToOpenAI,
        // which works functionally but loses semantic meaning for /responses.
        if (msg.content) {
          input.push({
            type: "message",
            role: "assistant",
            content: translateMessageContent(msg.content),
          })
        }
        if (msg.tool_calls) {
          for (const tc of msg.tool_calls) {
            input.push({
              type: "function_call",
              name: tc.function.name,
              arguments: tc.function.arguments,
              call_id: requireToolCallId(tc.id, "assistant tool call id"),
            })
          }
        }
        break
      }
      case "tool": {
        input.push({
          type: "function_call_output",
          call_id: requireToolCallId(
            msg.tool_call_id,
            "tool message tool_call_id",
          ),
          output:
            typeof msg.content === "string" ?
              msg.content
            : JSON.stringify(msg.content),
        })
        break
      }
      // No default
    }
  }
  return input
}
function translateTools(
  payload: ChatCompletionsPayload,
): Partial<ResponsesPayload> {
  const result: Partial<ResponsesPayload> = {}
  if (payload.tools) {
    result.tools = payload.tools.map((t) => ({
      type: "function" as const,
      name: t.function.name,
      description: t.function.description,
      parameters: t.function.parameters,
    }))
  }
  if (payload.tool_choice) {
    result.tool_choice =
      typeof payload.tool_choice === "string" ?
        payload.tool_choice
      : { type: "function", name: payload.tool_choice.function.name }
  }
  return result
}
export function translateRequestToResponses(
  payload: ChatCompletionsPayload,
  effort?: string,
): ResponsesPayload {
  const result: ResponsesPayload = {
    model: payload.model,
    input: translateMessages(payload.messages),
    stream: payload.stream ?? undefined,
    ...translateTools(payload),
  }
  if (payload.max_tokens !== null && payload.max_tokens !== undefined)
    result.max_output_tokens = payload.max_tokens
  if (effort) result.reasoning = { effort }
  return result
}
export interface ResponsesResponse {
  id: string
  object: string
  created_at?: number
  model: string
  output: Array<ResponsesOutputItem>
  usage?: {
    input_tokens: number
    output_tokens: number
    total_tokens: number
  }
  copilot_usage?: RawCopilotUsage
  status?: string
}
export type ResponsesOutputItem =
  | {
      type: "message"
      role: "assistant"
      content: Array<ResponsesMessageContent>
    }
  | { type: "function_call"; name: string; arguments: string; call_id: string }
  | {
      type: "reasoning"
      id: string
      summary?: Array<{ type: "summary_text"; text: string }>
      encrypted_content?: string | null
    }
export interface ResponsesMessageContent {
  type: "output_text"
  text: string
}
export function translateResponsesNonStreaming(
  resp: ResponsesResponse,
): ChatCompletionResponse {
  let textContent = ""
  let reasoningText = ""
  const toolCalls: Array<ToolCall> = []
  for (const item of resp.output) {
    switch (item.type) {
      case "message": {
        textContent += item.content.map((c) => c.text).join("")
        break
      }
      case "function_call": {
        toolCalls.push({
          id: item.call_id,
          type: "function",
          function: { name: item.name, arguments: item.arguments },
        })
        break
      }
      case "reasoning": {
        // Extract reasoning summary text if available
        if (item.summary && item.summary.length > 0) {
          reasoningText += item.summary.map((s) => s.text).join("\n")
        }
        break
      }
      // No default
    }
    // Skip other unknown item types
  }
  const finishReason = toolCalls.length > 0 ? "tool_calls" : "stop"
  return {
    id: resp.id,
    object: "chat.completion",
    created: resp.created_at ?? Math.floor(Date.now() / 1000),
    model: resp.model,
    choices: [
      {
        index: 0,
        message: {
          role: "assistant",
          content: textContent || null,
          ...(reasoningText ? { reasoning_text: reasoningText } : {}),
          ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
        },
        logprobs: null,
        finish_reason: finishReason,
      },
    ],
    usage:
      resp.usage ?
        {
          prompt_tokens: resp.usage.input_tokens,
          completion_tokens: resp.usage.output_tokens,
          total_tokens: resp.usage.total_tokens,
        }
      : undefined,
    copilot_usage: normalizeCopilotUsage(resp.copilot_usage),
  }
}
export interface ResponsesStreamState {
  responseId: string
  model: string
  toolCallIndex: number
  toolCallsByCallId: Partial<Record<string, ResponsesStreamToolCall>>
  toolCallsByOutputIndex: Partial<Record<number, ResponsesStreamToolCall>>
  fallbackId: string
  created: number
}
export function createResponsesStreamState(): ResponsesStreamState {
  return {
    responseId: "",
    model: "",
    toolCallIndex: 0,
    toolCallsByCallId: {},
    toolCallsByOutputIndex: {},
    fallbackId: `chatcmpl-${randomUUID()}`,
    created: Math.floor(Date.now() / 1000),
  }
}
interface ResponsesStreamToolCall {
  arguments: string
  callId: string
  index: number
  name: string
}
interface ResponsesStreamUsage {
  input_tokens: number
  output_tokens: number
  total_tokens: number
  input_tokens_details?: {
    cached_tokens: number
  }
}
interface ResponsesStreamResponse {
  id?: string
  model?: string
  usage?: ResponsesStreamUsage
  error?: {
    type?: string
    message?: string
  }
  incomplete_details?: {
    reason?: string
  }
}
interface ResponsesStreamItem {
  arguments?: string
  call_id?: string
  id?: string
  name?: string
  type?: string
}
interface ResponsesStreamEventData {
  arguments?: string
  call_id?: string
  code?: string
  delta?: string
  id?: string
  item?: ResponsesStreamItem
  message?: string
  model?: string
  name?: string
  output_index?: number
  response?: ResponsesStreamResponse
}
function makeChunk(
  streamState: ResponsesStreamState,
  {
    delta,
    finishReason,
    usage,
  }: {
    delta: ChatCompletionChunk["choices"][0]["delta"]
    finishReason: string | null
    usage?: ChatCompletionChunk["usage"]
  },
): ChatCompletionChunk {
  return {
    id: streamState.responseId || streamState.fallbackId,
    object: "chat.completion.chunk",
    created: streamState.created,
    model: streamState.model,
    usage,
    choices: [
      {
        index: 0,
        delta,
        finish_reason:
          finishReason as ChatCompletionChunk["choices"][0]["finish_reason"],
        logprobs: null,
      },
    ],
  }
}
function syncResponseMetadata(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
) {
  if (!streamState.responseId) {
    streamState.responseId = data.response?.id ?? data.id ?? ""
  }
  if (!streamState.model) {
    streamState.model = data.response?.model ?? data.model ?? ""
  }
}
function translateResponsesUsage(
  usage: ResponsesStreamUsage | undefined,
): ChatCompletionChunk["usage"] | undefined {
  if (!usage) {
    return undefined
  }
  return {
    prompt_tokens: usage.input_tokens,
    completion_tokens: usage.output_tokens,
    total_tokens: usage.total_tokens,
    ...(usage.input_tokens_details && {
      prompt_tokens_details: {
        cached_tokens: usage.input_tokens_details.cached_tokens,
      },
    }),
  }
}
function getToolCallDelta(
  toolCall: ResponsesStreamToolCall,
  argumentsChunk: string,
): ChatCompletionChunk["choices"][0]["delta"] {
  return {
    tool_calls: [
      {
        index: toolCall.index,
        function: { arguments: argumentsChunk },
      },
    ],
  }
}
function getNewToolCallDelta(
  toolCall: ResponsesStreamToolCall,
  argumentsChunk: string,
): ChatCompletionChunk["choices"][0]["delta"] {
  return {
    tool_calls: [
      {
        index: toolCall.index,
        id: toolCall.callId,
        type: "function",
        function: {
          name: toolCall.name,
          arguments: argumentsChunk,
        },
      },
    ],
  }
}
function getExistingToolCall(
  streamState: ResponsesStreamState,
  data: Pick<ResponsesStreamEventData, "call_id" | "output_index">,
): ResponsesStreamToolCall | undefined {
  if (data.output_index !== undefined) {
    const outputIndexToolCall =
      streamState.toolCallsByOutputIndex[data.output_index]
    if (outputIndexToolCall) {
      return outputIndexToolCall
    }
  }
  return data.call_id ? streamState.toolCallsByCallId[data.call_id] : undefined
}
function getOrCreateToolCall(
  streamState: ResponsesStreamState,
  {
    callId,
    initialArguments = "",
    name,
    outputIndex,
  }: {
    callId?: string
    initialArguments?: string
    name?: string
    outputIndex?: number
  },
): { isNew: boolean; toolCall: ResponsesStreamToolCall } | undefined {
  if (!callId || !name) {
    return undefined
  }
  const existingToolCall =
    streamState.toolCallsByCallId[callId]
    ?? (outputIndex !== undefined ?
      streamState.toolCallsByOutputIndex[outputIndex]
    : undefined)
  if (existingToolCall) {
    streamState.toolCallsByCallId[callId] = existingToolCall
    if (outputIndex !== undefined) {
      streamState.toolCallsByOutputIndex[outputIndex] = existingToolCall
    }
    return { isNew: false, toolCall: existingToolCall }
  }
  const toolCall: ResponsesStreamToolCall = {
    arguments: initialArguments,
    callId,
    index: streamState.toolCallIndex,
    name,
  }
  streamState.toolCallsByCallId[callId] = toolCall
  if (outputIndex !== undefined) {
    streamState.toolCallsByOutputIndex[outputIndex] = toolCall
  }
  streamState.toolCallIndex++
  return { isNew: true, toolCall }
}
function* syncToolArguments(
  streamState: ResponsesStreamState,
  toolCall: ResponsesStreamToolCall,
  nextArguments: string | undefined,
): Generator<ChatCompletionChunk> {
  if (!nextArguments || nextArguments === toolCall.arguments) {
    return
  }
  if (!nextArguments.startsWith(toolCall.arguments)) {
    consola.warn(
      "Tool call argument stream diverged; preserving streamed prefix",
      {
        callId: toolCall.callId,
        name: toolCall.name,
        accumulatedLength: toolCall.arguments.length,
        candidateLength: nextArguments.length,
        accumulatedTail: toolCall.arguments.slice(-80),
        candidateHead: nextArguments.slice(0, 80),
      },
    )
    return
  }
  const missingArguments = nextArguments.slice(toolCall.arguments.length)
  toolCall.arguments = nextArguments
  if (!missingArguments) {
    return
  }
  yield makeChunk(streamState, {
    delta: getToolCallDelta(toolCall, missingArguments),
    finishReason: null,
  })
}
function* handleCreatedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  yield makeChunk(streamState, {
    delta: { role: "assistant", content: "" },
    finishReason: null,
  })
}
function* handleOutputTextDeltaEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (!data.delta) {
    return
  }
  yield makeChunk(streamState, {
    delta: { content: data.delta },
    finishReason: null,
  })
}
function* handleOutputItemAddedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (data.item?.type !== "function_call") {
    return
  }
  const toolCall = getOrCreateToolCall(streamState, {
    callId: data.item.call_id,
    initialArguments: data.item.arguments ?? "",
    name: data.item.name,
    outputIndex: data.output_index,
  })
  if (!toolCall?.isNew) {
    return
  }
  yield makeChunk(streamState, {
    delta: getNewToolCallDelta(toolCall.toolCall, data.item.arguments ?? ""),
    finishReason: null,
  })
}
function* handleFunctionCallArgumentsDeltaEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (!data.delta) {
    return
  }
  const existingToolCall = getExistingToolCall(streamState, data)
  if (existingToolCall) {
    existingToolCall.arguments += data.delta
    yield makeChunk(streamState, {
      delta: getToolCallDelta(existingToolCall, data.delta),
      finishReason: null,
    })
    return
  }
  const toolCall = getOrCreateToolCall(streamState, {
    callId: data.call_id,
    initialArguments: data.delta,
    name: data.name,
    outputIndex: data.output_index,
  })
  if (!toolCall) {
    return
  }
  yield makeChunk(streamState, {
    delta: getNewToolCallDelta(toolCall.toolCall, data.delta),
    finishReason: null,
  })
}
function* handleFunctionCallArgumentsDoneEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  const existingToolCall = getExistingToolCall(streamState, data)
  if (!existingToolCall) {
    return
  }
  yield* syncToolArguments(streamState, existingToolCall, data.arguments)
}
function getExistingOrCreateCompletedToolCall(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): { isNew: boolean; toolCall: ResponsesStreamToolCall } | undefined {
  const existingToolCall = getExistingToolCall(streamState, {
    call_id: data.item?.call_id,
    output_index: data.output_index,
  })
  if (existingToolCall) {
    return { isNew: false, toolCall: existingToolCall }
  }
  return getOrCreateToolCall(streamState, {
    callId: data.item?.call_id,
    initialArguments: data.item?.arguments ?? "",
    name: data.item?.name,
    outputIndex: data.output_index,
  })
}
function* handleOutputItemDoneEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (data.item?.type !== "function_call") {
    return
  }
  const toolCall = getExistingOrCreateCompletedToolCall(streamState, data)
  if (!toolCall) {
    return
  }
  if (toolCall.isNew) {
    yield makeChunk(streamState, {
      delta: getNewToolCallDelta(toolCall.toolCall, data.item.arguments ?? ""),
      finishReason: null,
    })
  }
  yield* syncToolArguments(streamState, toolCall.toolCall, data.item.arguments)
}
function* handleCompletedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const hasToolCalls = Object.keys(streamState.toolCallsByCallId).length > 0
  yield makeChunk(streamState, {
    delta: {},
    finishReason: hasToolCalls ? "tool_calls" : "stop",
    usage: translateResponsesUsage(data.response?.usage),
  })
}
function mapIncompleteReasonToFinishReason(
  reason: string | undefined,
): "stop" | "length" | "content_filter" {
  switch (reason) {
    case "max_output_tokens": {
      return "length"
    }
    case "content_filter": {
      return "content_filter"
    }
    default: {
      return "stop"
    }
  }
}
function* handleFailedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const errorType = data.response?.error?.type ?? "api_error"
  const message = data.response?.error?.message ?? "Upstream response failed"
  consola.warn("Upstream /responses failed", { type: errorType, message })
  const chunk = makeChunk(streamState, {
    delta: {},
    finishReason: null,
    usage: translateResponsesUsage(data.response?.usage),
  })
  chunk.error = { type: errorType, message }
  yield chunk
}
function* handleErrorEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  const errorType = data.code ?? "api_error"
  const message = data.message ?? "Upstream error"
  consola.warn("Upstream /responses error event", {
    type: errorType,
    message,
  })
  const chunk = makeChunk(streamState, {
    delta: {},
    finishReason: null,
  })
  chunk.error = { type: errorType, message, code: data.code }
  yield chunk
}
function* handleIncompleteEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const finishReason = mapIncompleteReasonToFinishReason(
    data.response?.incomplete_details?.reason,
  )
  yield makeChunk(streamState, {
    delta: {},
    finishReason,
    usage: translateResponsesUsage(data.response?.usage),
  })
}
export function* translateResponsesStreamEvent(
  event: {
    event: string
    data: ResponsesStreamEventData
  },
  streamState: ResponsesStreamState,
): Generator<ChatCompletionChunk> {
  const { event: eventType, data } = event
  switch (eventType) {
    case "response.created": {
      yield* handleCreatedEvent(streamState, data)
      break
    }
    case "response.in_progress": {
      syncResponseMetadata(streamState, data)
      break
    }
    case "response.output_text.delta": {
      yield* handleOutputTextDeltaEvent(streamState, data)
      break
    }
    case "response.output_item.added": {
      yield* handleOutputItemAddedEvent(streamState, data)
      break
    }
    case "response.function_call_arguments.delta": {
      yield* handleFunctionCallArgumentsDeltaEvent(streamState, data)
      break
    }
    case "response.function_call_arguments.done": {
      yield* handleFunctionCallArgumentsDoneEvent(streamState, data)
      break
    }
    case "response.output_item.done": {
      yield* handleOutputItemDoneEvent(streamState, data)
      break
    }
    case "response.completed": {
      yield* handleCompletedEvent(streamState, data)
      break
    }
    case "response.failed": {
      yield* handleFailedEvent(streamState, data)
      break
    }
    case "response.incomplete": {
      yield* handleIncompleteEvent(streamState, data)
      break
    }
    case "error": {
      yield* handleErrorEvent(streamState, data)
      break
    }
    default: {
      break
    }
  }
}
export async function createResponses(
  payload: ChatCompletionsPayload,
  effort?: string,
  signal?: AbortSignal,
): Promise<ServiceResult<ChatCompletionResponse, ResponsesStream>> {
  if (!state.copilotToken) throw new Error("Copilot token not found")
  const responsesPayload = translateRequestToResponses(payload, effort)
  const url = `${copilotBaseUrl(state)}/responses`
  consola.debug(`Sending /responses request for model: ${payload.model}`)
  const response = await copilotFetch(url, {
    method: "POST",
    body: JSON.stringify(responsesPayload),
    signal,
  })
  if (!response.ok) {
    consola.error("Failed to create responses", response)
    throw new HTTPError("Failed to create responses", response)
  }
  if (payload.stream) {
    return streamResult(events(response))
  }
  const rawResponse = (await response.json()) as ResponsesResponse
  return objectResult(translateResponsesNonStreaming(rawResponse))
}

export type ServiceResult<TBody, TStream> =
  | { kind: "object"; body: TBody }
  | { kind: "stream"; stream: TStream }

export const objectResult = <T>(body: T) => ({ kind: "object", body }) as const
export const streamResult = <T>(stream: T) =>
  ({ kind: "stream", stream }) as const

